window.ScripturaLexicons.BDAG_PART_0324 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-01\" data-source=\"BDAG\" data-search=\"σιτία, ας, ἡ substantivo feminino porção de massa; massa de pão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιτία, ας, ἡ</td><td>substantivo feminino</td><td>porção de massa; massa de pão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-02\" data-source=\"BDAG\" data-search=\"σιτίον, ου, τό substantivo neutro alimento, víveres BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιτίον, ου, τό</td><td>substantivo neutro</td><td>alimento, víveres</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-03\" data-source=\"BDAG\" data-search=\"σιτιστός, ή, όν adjetivo; substantivado cevado, engordado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιτιστός, ή, όν</td><td>adjetivo; substantivado</td><td>cevado, engordado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-04\" data-source=\"BDAG\" data-search=\"σιτομέτριον, ου, τό substantivo neutro ração, porção de alimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιτομέτριον, ου, τό</td><td>substantivo neutro</td><td>ração, porção de alimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-05\" data-source=\"BDAG\" data-search=\"σῖτος, ου, ὁ substantivo masculino trigo; cereal, grão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σῖτος, ου, ὁ</td><td>substantivo masculino</td><td>trigo; cereal, grão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-06\" data-source=\"BDAG\" data-search=\"σίφων, ωνος, ὁ substantivo masculino bomba de água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σίφων, ωνος, ὁ</td><td>substantivo masculino</td><td>bomba de água</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-07\" data-source=\"BDAG\" data-search=\"σιφωνίζω verbo esguichar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιφωνίζω</td><td>verbo</td><td>esguichar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-08\" data-source=\"BDAG\" data-search=\"Σιχάρ nome próprio; variante ver Συχάρ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σιχάρ</td><td>nome próprio; variante</td><td>ver Συχάρ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-09\" data-source=\"BDAG\" data-search=\"Σιών, ἡ nome próprio feminino indeclinável Sião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σιών, ἡ</td><td>nome próprio feminino indeclinável</td><td>Sião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-10\" data-source=\"BDAG\" data-search=\"σιωπάω verbo guardar silêncio, calar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιωπάω</td><td>verbo</td><td>guardar silêncio, calar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-11\" data-source=\"BDAG\" data-search=\"σιωπῇ advérbio; dativo em voz baixa, em particular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σιωπῇ</td><td>advérbio; dativo</td><td>em voz baixa, em particular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-12\" data-source=\"BDAG\" data-search=\"σκάμμα, ατος, τό substantivo neutro fosso, arena BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκάμμα, ατος, τό</td><td>substantivo neutro</td><td>fosso, arena</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-13\" data-source=\"BDAG\" data-search=\"σκανδαλίζω verbo levar ao pecado; escandalizar, ofender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκανδαλίζω</td><td>verbo</td><td>levar ao pecado; escandalizar, ofender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-14\" data-source=\"BDAG\" data-search=\"σκάνδαλον, ου, τό substantivo neutro armadilha; tentação; motivo de escândalo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκάνδαλον, ου, τό</td><td>substantivo neutro</td><td>armadilha; tentação; motivo de escândalo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-15\" data-source=\"BDAG\" data-search=\"σκάπτω verbo cavar, escavar; cultivar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκάπτω</td><td>verbo</td><td>cavar, escavar; cultivar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-16\" data-source=\"BDAG\" data-search=\"Σκαριώθ nome próprio; variante variante de Iscariotes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σκαριώθ</td><td>nome próprio; variante</td><td>variante de Iscariotes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-17\" data-source=\"BDAG\" data-search=\"Σκαριώτης nome próprio; variante ver Ἰσκαριώθ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σκαριώτης</td><td>nome próprio; variante</td><td>ver Ἰσκαριώθ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-18\" data-source=\"BDAG\" data-search=\"σκάφη, ης, ἡ substantivo feminino tigela; bote, pequena embarcação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκάφη, ης, ἡ</td><td>substantivo feminino</td><td>tigela; bote, pequena embarcação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-19\" data-source=\"BDAG\" data-search=\"σκελοκοπέω verbo quebrar as pernas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκελοκοπέω</td><td>verbo</td><td>quebrar as pernas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0324-20\" data-source=\"BDAG\" data-search=\"σκέλος, ους, τό substantivo neutro perna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκέλος, ους, τό</td><td>substantivo neutro</td><td>perna</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0324-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιτία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (escritores cristãos; Hesychius.—<span class=\"greek\">σιτεία</span>=alimentação, engorda encontra-se já em PCairZen 534, 1 [III a.C.]. Trata-se de uma palavra diferente, de <span class=\"greek\">σιτεύω</span>=alimentar, engordar, ou apenas de outra grafia?) uma porção de massa, massa (assim Apophtheg. Patrum [c. VI d.C.]: MPG LXV 192a; 196b) <span class=\"greek\">ς</span>. <span class=\"greek\">ποιεῖν</span> fazer pão, assar pão D 13:5.—DELG s.v. <span class=\"greek\">σῖτος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιτίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hdt., Aristoph.+; PGiss 19, 2; POxy 1158, 11; Pr 30:22; TestSol; JosAs 13:7 [codd. AB em lugar de <span class=\"greek\">σιτιστά</span>]; Philo; Joseph.; prim.: ‘grão’ ou ‘alimento feito de grãos’) dim. de <span class=\"greek\">σῖτος</span>; principalmente, e em nossa lit. sempre, no pl. <span class=\"greek\">τὰ</span> <span class=\"greek\">σιτία</span> e em referência geral a víveres, alimento (freq. em Hdt. et al.; pap.; Jos., Ant. 4, 270; 15, 300) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:12</a>. <span class=\"greek\">σιτία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτά</span> comida e bebida (v. <span class=\"greek\">ποτόν</span>; também HMørland, SymbOsl 13, ’34, 103; LDeubner, SBBerlAk ’35, XIX, 71) Dg 6:9.—B. 329. DELG s.v. <span class=\"greek\">σῖτος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτιστός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιτιστός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σιτεύω</span> ‘alimentar, engordar’) cevado (Athen. 14, 656e <span class=\"greek\">ὄρνιθες</span>; Herodian. Gramm., Philet. 152 [Dain] <span class=\"greek\">σιτευτοὺς</span> <span class=\"greek\">ὄρνιθας</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">σιτιστούς</span>; JosAs 10:14; 13:7; Jos., Ant. 8, 40 <span class=\"greek\">βόες</span>; Ps 21:13 Sym.; Jer 46:21 Sym. [=Jer 26:21 LXX, que apresenta <span class=\"greek\">σιτευτοί</span>]) subst. <span class=\"greek\">τὰ</span> <span class=\"greek\">σιτιστά</span> gado que foi cevado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:4</a>.—DELG s.v. <span class=\"greek\">σῖτος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτομέτριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιτομέτριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σιτομετρέω</span> ‘distribuir grãos’) uma porção medida de grãos/alimento, porção de alimento, ração (PPetr II, 33a, 5 [v. Dssm., B 156, 5 (BS 158, 1); Mayser 431]; inscr. de Rodiápolis, na Lícia, de 149 d.C. [RHeberdey, Opramoas 1897 p. 50 col. XIX A, 8=IGR III, 739, col. XIX, 8, um bilionário assegura o abastecimento de grãos à população; v. Dssm., LO 82, 1=LAE 104, 1] <span class=\"greek\">σειτομέτριον</span>; Rhet. Gr. VI 226, 29.—<span class=\"greek\">σιτομετρία</span> é mais comum) <span class=\"greek\">διδόναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. distribuir a porção de alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a>.—New Docs 2, 8. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῖτος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σῖτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; inscr., pap., LXX, JosAs; ApcEsdr 5:12 p. 30, 6 Tdf.; SibOr, Philo Jos., Vi. 71; Ath. 22, 6) trigo, mas também grãos em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:25</a>, 29 (ervas daninhas entre eles, como SibOr 1, 397); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:6</a> (sobre isso v. Diod S 14, 111, 1 como indicação de grave fome e elevação dos preços <span class=\"greek\">πέντε</span> <span class=\"greek\">μνῶν</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μέδιμνον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σίτου</span>=uma medida (bushel) de grãos vendido por cinco minas; Jos., Ant. 14, 28); 18:13. <span class=\"greek\">κόκκος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:37</a> (cf. ApcEsdr 5:12 <span class=\"greek\">τὸν</span> <span class=\"greek\">σπόρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σίτου</span>; granum tritici Papias [1, 3]). <span class=\"greek\">συνάγειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀποθήκην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:12</a>; 13:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:17</a>; cf. 12:18. <span class=\"greek\">σινιάσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ς</span>. 22:31. Como carga de um navio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:38</a>. <span class=\"greek\">ς</span>. <span class=\"greek\">ὥριμος</span> 1 Cl 56:15 (Job 5:26). Para <span class=\"greek\">πλήρης</span> <span class=\"greek\">σῖτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:28</a> v. <span class=\"greek\">πλήρης</span> 2.—Pl. <span class=\"greek\">τὰ</span> <span class=\"greek\">σῖτα</span> (Hdt.+; Philo, Det. Pot. Ins. 19 e LXX, onde essa forma ocorre em Job e Pr; mas o pl. não se encontra em nenhum outro livro; v. Thackeray 155.—B-D-F §49, 3; Mlt-H. 122; 372) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:12</a> v.l. Inácio, em seu ardente anseio pelo martírio, emprega esta imagem: <span class=\"greek\">σῖτός</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">θεοῦ</span> sou trigo de Deus e serei moído pelos dentes das feras IRo 4:1.—B. 514; Pauly-W. Suppl. VI (1935) 819ff; I (1894) 261ff; VII (1912) 1336ff; Kl. Pauly V 217–19; BHHW I 563. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίφων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σίφων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (desde Hipponax [VI a.C.] 52 D.3; Eur., Hippocr.; PEleph 5, 4 [III a.C.]; PLond 1177, 129; empréstimo no rabínico) bomba de água (vários tipos empregados na agricultura e no combate a incêndios Hero Alex. I p. 18, 2; 28, 18 al.) Hm 11:18.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιφωνίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιφωνίζω</span> (<span class=\"greek\">σίφων</span>) 1 aor. <span class=\"greek\">ἐσιφώνισα</span> (Aristoph., Thesm. 557) esguichar Hm 11:18.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σιχάρ</h1><div class=\"entry-meta\"><span>nome próprio; variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σιχάρ</span> v. <span class=\"greek\">Συχάρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σιών, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σιών</span>, <span class=\"greek\">ἡ</span> indecl. (<span class=\"hebrew\">צִיּוֹן</span>; LXX; PsSol 11:1; TestSol; ParJer 7:33; Mel., P. 7, 47; sobre a grafia v. B-D-F §38; 56, 3; cf. Mlt-H. 149) Sião, empregado a respeito de</p><p class=\"entry-text\">① monte Sião, uma colina dentro da cidade de Jerusalém (Dalman, PJ 11, 1915, 39ff. V. <span class=\"greek\">Ἱεροσόλυμα</span> 1) <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">Σιών</span>, o lugar onde o Cordeiro está de pé com seu povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:1</a>. Em linguagem figurada como contraparte do Sinai (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:24</a>–26; Ps.-Cyprian, De Montibus Sina et Sion: Cyprian III p. 104ff Hartel) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a> (cf. Mel., P. 47 <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐγένετο</span> … <span class=\"greek\">συνεξελθὼν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Ζιὼν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἱερουσαλήμ</span>).</p><p class=\"entry-text\">② a cidade de Jerusalém (Jer 3:14 et al.; cf. 11 Qps 22:1–15). <span class=\"greek\">ἡ</span> <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">Σιών</span> da cidade de Jerusalém e de seus habitantes (v. <span class=\"greek\">θυγάτηρ</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:15</a> (ambos Zech 9:9; v. SibOr 324).</p><p class=\"entry-text\">③ o povo de Deus</p><p class=\"entry-text\">ⓐ o povo de Israel, cujo centro é Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a>; B 6:2 (ambos Is 28:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:26</a> (Is 59:20).</p><p class=\"entry-text\">ⓑ a Nova Jerusalém da promessa profética <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a> (Is 28:16).—BHHW III 2242f. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιωπάω</span> imperf. <span class=\"greek\">ἐσιώπων</span>; fut. <span class=\"greek\">σιωπήσω</span>; 1 aor. <span class=\"greek\">ἐσιώπησα</span>; perf. 1 pl. <span class=\"greek\">σεσιωπήκαμεν</span> Job 18:3; fut. méd. <span class=\"greek\">σιωπήσομαι</span> LXX (Hom. et al.; pap., LXX; TestSol 6:11; TestJob, Test12Patr, ParJer, Philo; Jos., Vi. 195; 338; Mel., P. 25, 177; Ath. 21, 3) prim. ‘estar em silêncio’.</p><p class=\"entry-text\">① abster-se de falar ou produzir um som, guardar silêncio, nada dizer, não produzir som algum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a> (Maximus Tyr. 3, 7e, Sócrates perante um júri. Sobre o assunto cf. Diog. L. 3, 19 Platão perante a assembleia popular em Egina, em julgamento no qual sua vida estava em jogo: <span class=\"greek\">μηδ</span>’ <span class=\"greek\">ὁτιοῦν</span> <span class=\"greek\">φθέγξασθαι</span>=não disse uma única palavra; Eur. em Plut., Mor. 532f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:4</a>; 9:34; 14:61; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:9</a> (op. <span class=\"greek\">λαλεῖν</span> como PGM 5, 292; cf. Theophr., Charac. 7); IEph 15:1 (op. <span class=\"greek\">λαλεῖν</span>); IRo 2:1a; GPt 4:10. <span class=\"greek\">ς</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> guardar silêncio a respeito de alguém IEph 3:2. <span class=\"greek\">ς</span>. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> guardar silêncio e deixar alguém em paz IRo 2:1b.</p><p class=\"entry-text\">② interromper o processo de falar ou produzir um som, parar de falar, estar/ficar quieto</p><p class=\"entry-text\">ⓐ de seres humanos (Menand., Georg. 54; Plut., Mor. 434f; Herm. Wr. 1, 16; TestJos 9:4; Jos., Ant. 7, 378; Mel., P. 25, 177) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a> v.l.; 19:40; MPol 7:3; GMary 463, 3—Calar-se no sentido de perder a faculdade da fala <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>.</p><p class=\"entry-text\">ⓑ não de seres humanos: de porcos B 10:3 (op. <span class=\"greek\">κραυγάζειν</span>).—Metaf., do vento e das ondas numa tempestade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:39</a> (cf. a imagem Theocr., Idyll 2, 38 <span class=\"greek\">σιγᾷ</span> <span class=\"greek\">πόντος</span>).—B. 1259. Schmidt, Syn. I 224. DELG. M-M. V. <span class=\"greek\">σιγάω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπῇ</h1><div class=\"entry-meta\"><span>advérbio; dativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σιωπῇ</span> dat. de <span class=\"greek\">σιωπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> ‘silêncio’ (como subst. Soph., X.+; inscr., pap., LXX; TestAbr A 16 p. 98, 11 [Stone p. 44] <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">γενόμενος</span>; Joseph., Philo; Mel., P. 25, 179 <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ς</span>.) como adv. (já em Hom.; X., Cyr. 5, 3, 43; Ps.-Demosth. 48, 31; SIG 1218, 11 [V a.C.]) relativo ao que é dito sem que outros ouçam, em voz baixa, em particular <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:28</a> D e versões.—DELG s.v. <span class=\"greek\">σιωπάω</span>. M-M s.v. <span class=\"greek\">σιωπάω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκάμμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σκάπτω</span>; Pla. et al.) ‘algo que foi escavado, trincheira’ (PCol IV, 78 passim [III a.C.]), depois arena (circundada por uma trincheira, ou escavada e coberta de areia; CIG 2758), especialmente empregado em sentido metaf. (Polyb. 38, 18, 5; Epict. 4, 8, 26) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">εἶναι</span> estar na mesma arena 1 Cl 7:1.—DELG s.v. <span class=\"greek\">σκάπτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκανδαλίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκανδαλίζω</span> (<span class=\"greek\">σκάνδαλον</span>) 1 aor. <span class=\"greek\">ἐσκανδάλισα</span>. Pass.: 1 fut. <span class=\"greek\">σκανδαλισθήσομαι</span>; 1 aor. <span class=\"greek\">ἐσκανδαλίσθην</span>; part. perf. <span class=\"greek\">ἐσκανδαλισμένος</span>; (LXX, Aq., Sym., Theod.; PsSol 16:7; TestSol; AscIs 3:14 [mas não em Test12Patr, EpArist, Philo, Joseph., apolog.]; Cat. Cod. Astr. X 67, 23; autores cristãos).</p><p class=\"entry-text\">① causar a queda, levar ao pecado (o pecado pode consistir em transgressão da lei moral, em incredulidade ou na aceitação de falsos ensinamentos)</p><p class=\"entry-text\">ⓐ <span class=\"greek\">τινά</span> alguém (Mal 2:8 Sym., Theod.; PsSol 16:7 <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">σκανδαλιζούσης</span> <span class=\"greek\">ἄφρονα</span>; Palladius 5 p. 21 <span class=\"greek\">σκανδαλίσαι</span> <span class=\"greek\">ψυχήν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29</a>f; 18:6, 8f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>f, 45, 47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:13</a>ab; 1 Cl 46:8.—Pass. ser levado ao pecado (Sir 23:8; 32:15; AcJ 82 [Aa II/1, 192, 1]) assim talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:29</a> (v. 2 abaixo).—O pass. abs. também pode significar deixar-se levar ao pecado (sobre a ‘passiva permissiva’ v. Gildersleeve, Syntax I §167), apostatar (Passio Perpet. 20, 10 vGebh.; MartPt 3 [Aa I p. 82, 22]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:21</a>; 24:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:17</a>; 14:27, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:1</a>; D 16:5.—<span class=\"greek\">ἐσκανδαλισμένοι</span> Hv 4, 1, 3; m 8:10 são pessoas que foram desviadas, mas que não abandonaram completamente a fé.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">σκανδαλίζεσθαι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Sir 9:5; 23:8; 32:15) ser levado ao pecado, sentir repulsa por alguém, referido a Jesus; recusando-se a crer nele ou apostatando dele, uma pessoa cai em pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:6</a>; 13:57; 26:31, 33 (cf. AscIs 3, 14 <span class=\"greek\">δώδεκα</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σκανδαλισθήσονται</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:23</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">σκανδαλίζεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a> v.l.</p><p class=\"entry-text\">② chocar por palavra ou ação, ofender, irritar, chocar (AcJ 56 [Aa II/1 p. 178, 35]; Athanasius, Vita Anton. 81; Palladius 37 p. 115 <span class=\"greek\">σκανδαλίζω</span> <span class=\"greek\">πολλούς</span>; 46 p. 136) <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:27</a> (JDerrett, NovT 6, ’63, 1–15); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.61\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:61</a>. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:12</a>.—<span class=\"greek\">τίς</span> <span class=\"greek\">σκανδαλίζεται</span>; talvez quem tem algum motivo para se sentir ofendido? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:29</a> (v. 1a acima).—V. <span class=\"greek\">σκάνδαλον</span>, fim.—DELG s.v. <span class=\"greek\">σκάνδαλον</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάνδαλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκάνδαλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (v. <span class=\"greek\">σκανδαλίζω</span>; pap. não bíbl.; PLond 1338, 25; 1339, 10 [ambos 709 d.C.]; LXX, Aq., Sym., Theod.; PsSol 4:23 [mas não em Test12Patr, EpArist, Philo, Joseph., apolog.], depois escritores cristãos. Palavra tardia em lugar de <span class=\"greek\">σκανδάληθρον</span> [Aristoph. et al.]; v. Hesych. e Phot. s.v.).</p><p class=\"entry-text\">① dispositivo para capturar algo vivo, armadilha (PCairZen 608, 7 [III a.C.], onde se escreve <span class=\"greek\">σκάνδαδον</span>) com <span class=\"greek\">παγίς</span>, usado metaf. (Josh 23:13; Ps 140:9; 1 Macc 5:4; Is 8:14 Sym. e Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:9</a> (Ps 68:23). <span class=\"greek\">σκ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> em tal pessoa não há motivo de queda, i.e., como indica o vs. seguinte, a pessoa pode ver o que se encontra ao longo do caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:10</a> (Moffatt ‘nenhuma armadilha’; v. AVicentCernuda, EstBîbl 27, ’68, 153–75, 215–32); mas v. 3.</p><p class=\"entry-text\">② ação ou circunstância que leva alguém a agir contrariamente a um modo apropriado de proceder ou a um conjunto de crenças, tentação ao pecado, incitamento à apostasia, à falsa crença etc., extensão fig. de 1 (Ezk 7:19 Aq. e Sym.; Wsd 14:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:7</a>abc; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:1</a>; B 4:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλειον</span> <span class=\"greek\">σκ</span>. a tentação final 4:3. <span class=\"greek\">βαλεῖν</span> <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">υἱῶν</span> <span class=\"greek\">Ἰσραήλ</span> incitar os filhos de Israel ao pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:14</a>. <span class=\"greek\">σκάνδαλα</span> <span class=\"greek\">ποιεῖν</span> provocar tentações (ao pecado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:17</a>. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">σκάνδαλον</span> pôr uma tentação no caminho de alguém 14:13 (sobre <span class=\"greek\">τιθέναι</span> <span class=\"greek\">σκ</span>. cf. Jdth 5:1); em lugar do dat. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> 1 Cl 35:8 (Ps 49:20).—Também de pessoas (PsSol 4:23; 1 Macc 5:4): Jesus repreende Pedro como Satanás <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ἐμοῦ</span> tu me estás tentando a pecar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:23</a>. Em <span class=\"greek\">ἀπεχόμενοι</span> <span class=\"greek\">σκανδάλων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψευδαδέλφων</span> <span class=\"greek\">κτλ</span>. Pol 6:3, <span class=\"greek\">σκ</span>. provavelmente se entende melhor como alguém que tenta outros a pecar (cf. Pistis Sophia 105; 106 [p. 173–75 CSchmidt] <span class=\"greek\">ὡς</span> <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">παραβάτης</span>; AcJ 64 [Aa II/1 p. 182, 14f] de uma mulher <span class=\"greek\">ἡ</span> <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">γενομένη</span> <span class=\"greek\">ἀνδρί</span>; 79 [p. 190, 11]).—Para aqueles que não conseguem decidir-se a crer nele, Jesus é um <span class=\"greek\">σκάνδαλον</span> (<span class=\"greek\">σκανδαλίζω</span> 1b). Em conformidade com a linguagem figurada do AT (Is 8:14, onde Aq., Sym., Theod.—em contraste com a LXX—têm nossa palavra), Jesus é chamado <span class=\"greek\">πέτρα</span> <span class=\"greek\">σκανδάλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a> (sobre a relação entre essas duas passagens v. RHarris, Testimonies I 1916, 18f; 26f).</p><p class=\"entry-text\">③ aquilo que causa ofensa ou repulsa e resulta em oposição, desaprovação ou hostilidade, falta, mancha etc. (Sir 7:6; 27:23). <span class=\"greek\">σκ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> nele não há mancha nem falta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:10</a> (cf. Jdth 5:20); mas v. 1. Da cruz <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀπιστοῦσιν</span> que é repulsiva para os que não têm fé IEph 18:1. O Cristo crucificado é um <span class=\"greek\">σκ</span>. para os judeus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:23</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σκάνδαλον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> a pedra de tropeço da cruz, i.e., aquilo que, na pregação acerca da cruz, suscita oposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:11</a>. <span class=\"greek\">συλλέξουσιν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σκ</span>. recolherão de seu reino tudo o que é ofensivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:41</a> (essa interpr., que refere <span class=\"greek\">τὰ</span> <span class=\"greek\">σκ</span>. a coisas, corresponderia à passagem da Escritura que serve de base a esta, i.e. Zeph 1:3, onde Sym. tem nossa palavra na combinação <span class=\"greek\">τὰ</span> <span class=\"greek\">σκάνδαλα</span> <span class=\"greek\">σὺν</span> [<span class=\"greek\">τοῖς</span>] <span class=\"greek\">ἀσεβέσι</span>. Mas o fato de Mt prosseguir com <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ποιοῦντας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνομίαν</span> poderia exigir que entendêssemos <span class=\"greek\">τὰ</span> <span class=\"greek\">σκ</span>. como pessoas; v. 2 acima).—À bibl. em TW acrescentar RKnox, Trials of a Translator ’49, 66–73; AHumbert, Biblica 35, ’54, 1–28 (sinóticos).—DELG. M-M. DBS XII 49–66. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκάπτω</span> fut. <span class=\"greek\">σκάψω</span>; 1 aor. <span class=\"greek\">ἔσκαψα</span>. Pass.: 2 aor. <span class=\"greek\">ἐσκάφην</span>; part. perf. <span class=\"greek\">ἐσκαμμένος</span> (v. <span class=\"greek\">σκάμμα</span>; Hom. Hymns, Thu. et al.; inscr., pap.; Is 5:6; TestJob 39:8, 11)</p><p class=\"entry-text\">① cavar o solo, cavar, intr. (Aristoph. et al.; BGU 1119, 23 [I a.C.] <span class=\"greek\">σκάπτειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτίζειν</span>) <span class=\"greek\">σκάπτειν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἰσχύω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:3</a> (v. textos citados em Wetstein; a expr. proverbial Aristoph., Av. 1432 <span class=\"greek\">σκάπτειν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίσταμαι</span> e Galen, Protr. 13 p. 42, 1ff John: <span class=\"greek\">ἰσχύς</span> suficiente para <span class=\"greek\">σκάπτειν</span>. Cavar é o tipo de trabalho mais árduo [Chariton 8, 8, 2; Appian, Liby. 15 §61]; um trabalhador sem instrução tem de dedicar-se a ele [Diog. L. 7, 169; Ps.-Phoc. 158]). <span class=\"greek\">σκ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">βαθύνειν</span> (v. <span class=\"greek\">βαθύνω</span>) 6:48 (Stephan. Byz. s.v. <span class=\"greek\">Ἄργιλος</span>: <span class=\"greek\">σκάπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεμελίους</span> <span class=\"greek\">καταβαλέσθαι</span>).</p><p class=\"entry-text\">② cavar para fins agrícolas, cultivar</p><p class=\"entry-text\">ⓐ intr. <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτήν</span> cavar em torno dela (com enxada ou enxadão), de uma figueira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a> (cf. Diod S 5, 41, 6 <span class=\"greek\">περισκαπφείσης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ῥίζων</span>).</p><p class=\"entry-text\">ⓑ trans. cavar, revolver a terra com a pá <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀμπελῶνα</span> (Diod S 4, 31, 7; PLond II, 163, 33 p. 183 [I d.C.]) Hs 5, 2, 4. Pass. (Is 5:6) 5, 2, 5; 5, 6, 2.—B. 497. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκαριώθ</h1><div class=\"entry-meta\"><span>nome próprio; variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σκαριώθ</span> a leitura de D em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.71\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:71</a> (em lugar de <span class=\"greek\">Ἰσκαριώτου</span>). V. verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκαριώτης</h1><div class=\"entry-meta\"><span>nome próprio; variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σκαριώτης</span> a leitura de D em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a>; 26:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:10</a>. V. <span class=\"greek\">Ἰσκαριώθ</span>. V. verbete precedente.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάφη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκάφη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σκάπτω</span>; Aeschyl., Hdt. et al.; inscr., pap.; Bel LXX 33, Theod. 33; [Test12 Patr e Philo <span class=\"greek\">σκάφο</span>]; Jos., C. Ap. 2, 11 [uma citação de Apion com <span class=\"greek\">σκάφη</span> como fem. sing.]; empréstimo no rabínico) em geral algo côncavo ou oco, como uma ‘tigela’, ‘bacia’ ou ‘tina’.</p><p class=\"entry-text\">① prato GJs 18:2 (codd.)</p><p class=\"entry-text\">② barco (pequeno), bote (assim Soph. et al.; Polyb. 1, 23, 7; PGradenwitz [SBHeidAk 1914] 9, 5 [III a.C.]; BGU 1157, 8; 1179; a transferência de sentido a partir da acepção 1 vê-se facilmente num trocadilho Ar., Eu. 1315: cf. nosso uso de ‘tina’ para um barco velho ou lento), de um bote de navio (normalmente a reboque, LCasson, Ships and Seamanship in the Ancient World, ’71, 248f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:16</a>, 30, 32.—B. 730. DELG s.v. <span class=\"greek\">σκάπτω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκελοκοπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκελοκοπέω</span> (provavelmente não <span class=\"greek\">σκελοκοπάω</span>) (<span class=\"greek\">σκέλος</span>, <span class=\"greek\">κόπος</span> ‘golpe’) 1 aor. pass. <span class=\"greek\">ἐσκελοκοπήθην</span> quebrar as pernas de alguém (v. <span class=\"greek\">σκέλος</span>) GPt 4:14 (cf. <span class=\"greek\">κατάγνυμι</span> e v. AKirk, NTS 40, ’94, 578–83).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0324-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκέλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκέλος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom.+; inscr., pap., LXX, EpArist, Philo; Jos., Ant. 3, 271) perna <span class=\"greek\">καταγνύναι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ς</span>. quebrar as pernas, da fratura dos ossos das pernas como punição, conhecida no lat. tardio como crurifragium (v. TLL s.v.). Orig. esta era uma forma distinta de pena capital, comparável à tortura na roda (v. <span class=\"greek\">κατάγνυμι</span> e KKohler, Das Verbot d. Knochenzerbrechens: ARW 13, 1910, 153f; uma punição de escravos desde pelo menos II a.C. [Plautus, As. 474 et al.]) Phlm subscr.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>–33 acompanhava a crucificação, a fim de apressar a morte (v. também Appian, Bell. Civ. 4, 44 §189 <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκέλος</span> <span class=\"greek\">συντριβέντοσ</span>= um [dos carregadores] quebrou a perna).—GBarton, ‘A Bone of Him Shall Not Be Broken’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:36</a>: JBL 49, 1930, 13–19; SHarrison, Cicero and ‘crurifragium’: ClQ n.s. 33, ’83, 453–55.—B. 241. DELG. M-M.</p></section></article>"};
